else:
    solution_str_clip = solution_str

if method == "strict":
    # this also tests the formatting of the model.
    # Search the FULL response, not just the trailing window: RL-trained models
    # frequently keep generating after emitting "#### <answer>", and in a long
    # response the answer then sits well outside the last 300 characters. Clipping
    # before matching makes a correct answer invisible and scores every such
    # rollout 0, collapsing the reward signal. The strict pattern remains the same.
    solutions = re.findall("#### (\\-?[0-9\\.\\,]+)", solution_str)
    if len(solutions) == 0:
        final_answer = None
    else:
        # take the last solution
        final_answer = solutions[-1].replace(",", "").replace("$", "")
elif method == "flexible":
    answer = re.findall("(\\-?[0-9\\.\\,]+)", solution_str)
    final_answer = None
    if len(answer) == 0:
        # no reward is there is no answer
        pass
    else:
        invalid_str = ["", "."]
        # find the last number that is not '.'
        for final_answer in reversed(answer):
            if final_answer not in invalid_str:
                break
return final_answer

