import sys; sys.path.insert(0, 'src/framework')
from verl.utils.reward_score import gsm8k

# Verify flexible path is byte-for-byte unchanged vs the original clip behavior
def original_extract(solution_str, method='strict'):
    CLIP = 300
    if len(solution_str) > CLIP:
        solution_str = solution_str[-CLIP:]
    if method == 'flexible':
        answer = __import__('re').findall('(\\\\-?[0-9\\\\.\\\\,]+)', solution_str)
        final_answer = None
        if len(answer) == 0:
            pass
        else:
            invalid_str = ['', '.']
            for final_answer in reversed(answer):
                if final_answer not in invalid_str:
                    break
        return final_answer

cases = [
